-- Perfiles comunitarios reales de MCU 5.0 (Básico/Estándar/Avanzado), con membresía
-- derivada de la columna 'Prioridad de implementación' de cada planilla oficial
-- (docs/mcu-5.0/Perfil comunitario *.xlsx): Básico = subcategorías Alta; Estándar = Alta +
-- Media; Avanzado = Alta + Media + Baja (el catálogo completo, salvo 3 subcategorías
-- 'No aplica'). Reemplaza la membresía de ejemplo sembrada en V8 (esa era ilustrativa,
-- sobre el catálogo de prueba de 15 controles que V9 acaba de reemplazar).
DELETE FROM prisma.community_profile_controls WHERE profile_id IN (
  'e1000001-0000-0000-0000-000000000001','e1000001-0000-0000-0000-000000000002','e1000001-0000-0000-0000-000000000003'
);

UPDATE prisma.community_profiles SET name = 'Básico', description = 'Subcategorías de prioridad Alta según el perfil comunitario Básico de MCU 5.0: la línea base mínima recomendada por Agesic.' WHERE id = 'e1000001-0000-0000-0000-000000000001';
UPDATE prisma.community_profiles SET name = 'Estándar', description = 'Subcategorías de prioridad Alta y Media según el perfil comunitario Estándar de MCU 5.0.' WHERE id = 'e1000001-0000-0000-0000-000000000002';
UPDATE prisma.community_profiles SET name = 'Avanzado', description = 'Todas las subcategorías aplicables (prioridad Alta, Media y Baja) según el perfil comunitario Avanzado de MCU 5.0 -- cobertura completa del catálogo.' WHERE id = 'e1000001-0000-0000-0000-000000000003';

